#!/usr/bin/env bash
set -euo pipefail
source "$(cd -P "$(dirname "${BASH_SOURCE[0]}")" && pwd)/common.sh"

config_dir="$PROJECT_DIR/.idea/runConfigurations"

if [ ! -d "$config_dir" ]; then
    echo -e "${YELLOW}No run configurations directory found.${NC}"
    exit 0
fi

# Find configs generated by ModdedTools (marked with comment)
files=()
for f in "$config_dir"/*.xml; do
    [ -f "$f" ] || continue
    if head -1 "$f" | grep -q "Generated by ModdedTools"; then
        files+=("$f")
    fi
done

if [ ${#files[@]} -eq 0 ]; then
    echo -e "${YELLOW}No ModdedTools-generated configs found.${NC}"
    exit 0
fi

echo "Found ${#files[@]} ModdedTools-generated config(s):"
for f in "${files[@]}"; do
    echo "  $(basename "$f")"
done

echo
echo "Delete these?"
select_option "Yes" "No" || choice=$?
choice=${choice:-0}

if [ "$choice" -eq 0 ]; then
    for f in "${files[@]}"; do
        rm "$f"
    done
    echo -e "${GREEN}Deleted ${#files[@]} config(s).${NC}"
else
    echo -e "${YELLOW}Cancelled.${NC}"
fi
